'use strict';
const SEED={projects:['Vadi İstanbul Konutları','Mavişehir Rezidans','Park Yaşam Evleri'],parties:[{id:'1',name:'Akçansa Çimento San. A.Ş.',code:'320.001',type:'320 Satıcılar'},{id:'2',name:'Yıldız Demir Çelik Ltd. Şti.',code:'320.002',type:'320 Satıcılar'},{id:'3',name:'Modern Yapı Malzemeleri',code:'320.003',type:'320 Satıcılar'},{id:'4',name:'Emre Yılmaz',code:'120.001',type:'120 Alıcılar'}],invoices:[{id:'FTR-2026-001',project:0,party:'1',date:'2026-11-02',due:'2026-11-18',base:450000,vat:20,rate:0.5,desc:'Beton ve çimento tedariği'},{id:'FTR-2026-002',project:0,party:'2',date:'2026-11-04',due:'2026-11-08',base:680000,vat:20,rate:0.7,desc:'İnşaat demiri alımı'},{id:'FTR-2026-003',project:0,party:'3',date:'2026-11-06',due:'2026-11-22',base:235000,vat:20,rate:0,desc:'Yalıtım ve yapı malzemeleri'},{id:'FTR-2026-004',project:1,party:'1',date:'2026-10-22',due:'2026-11-14',base:360000,vat:20,rate:0.5,desc:'Hazır beton alımı'},{id:'FTR-2026-005',project:2,party:'2',date:'2026-10-25',due:'2026-11-20',base:520000,vat:20,rate:0.7,desc:'Demir bağlantı elemanları'},{id:'FTR-2026-006',project:0,party:'1',date:'2026-10-18',due:'2026-11-01',base:300000,vat:20,rate:0.5,desc:'Temel beton dökümü'}],payments:[{id:'ODM-001',invoice:'FTR-2026-001',amount:250000,date:'2026-11-05',method:'Havale / EFT'},{id:'ODM-002',invoice:'FTR-2026-002',amount:420000,date:'2026-11-06',method:'Çek'},{id:'ODM-003',invoice:'FTR-2026-003',amount:282000,date:'2026-11-08',method:'Havale / EFT'},{id:'ODM-004',invoice:'FTR-2026-006',amount:200000,date:'2026-10-28',method:'Nakit'}],checks:[{id:'CK-001',project:0,party:'2',amount:420000,due:'2026-11-08',bank:'İş Bankası',status:'Portföyde',type:'Çek'},{id:'CK-002',project:0,party:'1',amount:180000,due:'2026-11-14',bank:'Garanti BBVA',status:'Portföyde',type:'Çek'},{id:'SN-001',project:1,party:'3',amount:125000,due:'2026-11-22',bank:'—',status:'Portföyde',type:'Senet'}],company:'Gündoğdu İnşaat A.Ş.'};
const PAGES=[['index.html','Genel Bakış','dashboard'],['faturalar.html','Faturalar','file'],['odemeler.html','Ödemeler','wallet'],['tevkifat.html','Tevkifat','percent'],['cek-senet.html','Çek / Senet','bank'],['cari-hesaplar.html','Cari Hesaplar','users'],['alicilar.html','120 Alıcılar','users'],['saticilar.html','320 Satıcılar','users'],['hesap-ekstresi.html','Hesap Ekstresi','transfer'],['raporlar.html','Raporlar','chart'],['ayarlar.html','Ayarlar','settings']];
const paths={building:'M6 22V3h12v19M3 22h18M9 6h1m4 0h1M9 10h1m4 0h1M9 14h1m4 0h1M10 22v-4h4v4',dashboard:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',file:'M14 2H6a2 2 0 0 0-2 2v16a2 2 0 0 0 2 2h12a2 2 0 0 0 2-2V8zM14 2v6h6M8 13h8M8 17h6',wallet:'M20 7V4H5a3 3 0 0 0 0 6h15v10H5a3 3 0 0 1-3-3V7m13 6h6v4h-6z',percent:'M19 5 5 19M7 3a3 3 0 1 0 0 6 3 3 0 0 0 0-6M17 15a3 3 0 1 0 0 6 3 3 0 0 0 0-6',bank:'m3 9 9-6 9 6H3zm0 12h18M6 12v6m6-6v6m6-6v6',users:'M16 21v-2a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v2M16 3a4 4 0 0 1 0 8m6 10v-2a4 4 0 0 0-3-3.87M13 7a4 4 0 1 0-8 0 4 4 0 0 0 8 0',transfer:'M4 7h16m-4-4 4 4-4 4M20 17H4m4-4-4 4 4 4',chart:'M3 3v18h18M7 14v3m5-9v9m5-13v13',settings:'M12 8a4 4 0 1 0 0 8 4 4 0 0 0 0-8M9 3l-1 3-3 1-2 3 2 2-1 3 3 2 2-1 3 2 3-2 2 1 3-2-1-3 2-2-2-3-3-1-1-3z',search:'M21 21l-5-5M18 10a8 8 0 1 0-16 0 8 8 0 0 0 16 0',bell:'M18 8a6 6 0 0 0-12 0c0 7-3 7-3 9h18c0-2-3-2-3-9M10 21h4',moon:'M21 13A9 9 0 0 1 11 3 9 9 0 1 0 21 13',plus:'M12 5v14M5 12h14',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',arrow:'M5 12h14m-6-6 6 6-6 6',chevron:'m9 5 7 7-7 7',check:'m5 12 4 4L19 6',close:'m6 6 12 12M6 18 18 6',calendar:'M4 5h16v16H4zM8 3v4m8-4v4M4 10h16',menu:'M3 6h18M3 12h18M3 18h18',clock:'M12 8v5l3 2M22 12a10 10 0 1 0-20 0 10 10 0 0 0 20 0',trash:'M3 6h18M8 6V3h8v3M6 6l1 15h10l1-15M10 10v7m4-7v7',print:'M6 9V3h12v6M6 17H3V9h18v8h-3M6 14h12v7H6z',upload:'M12 16V3m-5 5 5-5 5 5M4 16v5h16v-5',more:'M5 12h.01M12 12h.01M19 12h.01'};
function icon(name,size=18){return `<svg width="${size}" height="${size}" viewBox="0 0 24 24" fill="none" stroke="currentColor" stroke-width="1.7" stroke-linecap="round" stroke-linejoin="round" aria-hidden="true"><path d="${paths[name]||paths.file}"/></svg>`}
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const money=n=>new Intl.NumberFormat('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2}).format(Number(n)||0)+' ₺';
const fmtDate=d=>d?d.split('-').reverse().join('.'):'—';
const sum=(rows,fn)=>rows.reduce((s,x)=>s+fn(x),0);
let db=JSON.parse(JSON.stringify(SEED)),state={page:'Genel Bakış',project:'0',period:'all',search:'',status:'Tümü',report:0,cari:'',start:'',end:'',hidden:[],tab:'Tümü',detailTab:'Hareketler'},storageOK=true,lastFocus=null;
const today=()=>new Date().toLocaleDateString('sv-SE',{timeZone:'Europe/Istanbul'});
const party=id=>db.parties.find(p=>p.id===id)?.name||'—';
const net=i=>Math.round(i.base*(1+i.vat/100-i.vat/100*i.rate)*100)/100;
const paid=i=>sum(db.payments.filter(p=>p.invoice===i.id),p=>p.amount);
const remain=i=>Math.max(0,Math.round((net(i)-paid(i))*100)/100);
const billStatus=i=>remain(i)<.01?'Ödendi':paid(i)>0?'Kısmi ödendi':'Ödenmedi';
const scoped=x=>state.project==='all'||x.project===Number(state.project);
const bills=()=>db.invoices.filter(scoped).filter(i=>state.period==='all'||i.date.startsWith(state.period));
const pays=()=>db.payments.filter(p=>bills().some(i=>i.id===p.invoice));
const cheques=()=>db.checks.filter(scoped);
const scopeName=()=>state.project==='all'?'Tüm İnşaatlar':db.projects[Number(state.project)]||'Tüm İnşaatlar';
function filteredBills(){return bills().filter(i=>(i.id+' '+party(i.party)+' '+i.desc).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr'))&&(state.status==='Tümü'||billStatus(i)===state.status))}
function field(label,name,type='text',value='',attrs=''){return `<label class="field"><span>${label}</span><input class="w-full rounded-lg border px-3 py-2.5 focus:outline-2 focus:outline-offset-2" name="${name}" type="${type}" value="${esc(value)}" ${attrs}></label>`}
function options(arr,selected){return arr.map(x=>{const [v,label]=Array.isArray(x)?x:[x,x];return `<option value="${esc(v)}" ${String(v)===String(selected)?'selected':''}>${esc(label)}</option>`}).join('')}
function selectField(label,name,arr,value,attrs=''){return `<label class="field"><span>${label}</span><select class="w-full rounded-lg border px-3 py-2.5" name="${name}" ${attrs}>${options(arr,value)}</select></label>`}
function button(label,action,ico='plus',primary=false,attrs=''){return `<button type="button" data-action="${action}" class="${primary?'primary ':''}inline-flex items-center justify-center gap-2 rounded-lg text-xs font-medium transition-colors" ${attrs}>${icon(ico,16)}${label}</button>`}
function badge(text,color='blue'){return `<span class="badge ${color}">${esc(text)}</span>`}
function cardHead(title,sub='',right=''){return `<div class="cardhead flex items-center justify-between gap-3"><div><h2 class="font-semibold">${title}</h2>${sub?`<p>${sub}</p>`:''}</div>${right}</div>`}
function totals(){const a=bills();return {invoice:sum(a,net),payment:sum(pays(),p=>p.amount),debt:sum(a,remain),withheld:sum(a,i=>i.base*i.vat/100*i.rate)}}
function invoiceTable(rows,printing=false){const cols=[['id','Fatura / Açıklama'],['party','Cari hesap'],['date','Fatura tarihi'],['net','Net tutar'],['paid','Ödenen'],['remaining','Kalan'],['status','Durum']].filter(([k])=>printing||!state.hidden.includes(k));return `<div class="tablewrap overflow-x-auto"><table class="w-full text-left ${printing?'document-table':''}"><thead><tr>${cols.map(([k,label])=>`<th class="${['net','paid','remaining'].includes(k)?'num':''}">${label}</th>`).join('')}<th class="noprint"></th></tr></thead><tbody>${rows.map(i=>`<tr class="hover:bg-[#62766d]/5" data-detail="${esc(i.id)}">${cols.map(([k])=>{const val={id:`<b class="link">${esc(i.id)}</b><small>${esc(i.desc)}</small>`,party:`<b>${esc(party(i.party))}</b><small>${esc(db.projects[i.project])}</small>`,date:fmtDate(i.date),net:money(net(i)),paid:money(paid(i)),remaining:`<b>${money(remain(i))}</b><span class="progress"><i style="width:${Math.min(100,paid(i)/net(i)*100)}%"></i></span>`,status:badge(billStatus(i),remain(i)<.01?'green':paid(i)>0?'orange':'red')};return `<td class="${['net','paid','remaining'].includes(k)?'num tabular-nums':''}">${val[k]}</td>`}).join('')}<td class="noprint">${icon('chevron',15)}</td></tr>`).join('')}</tbody><tfoot><tr>${cols.map(([k],j)=>`<td class="${['net','paid','remaining'].includes(k)?'num tabular-nums':''}">${j===0?'Toplam · '+rows.length+' kayıt':k==='net'?money(sum(rows,net)):k==='paid'?money(sum(rows,paid)):k==='remaining'?money(sum(rows,remain)):''}</td>`).join('')}<td class="noprint"></td></tr></tfoot></table>${rows.length?'':'<div class="empty">Kayıt bulunamadı. Filtreleri değiştirin veya yeni kayıt ekleyin.</div>'}</div>`}
function metrics(){const t=totals(),c=cheques();return `<div class="stats grid grid-cols-2 xl:grid-cols-3 gap-4">${[['Toplam Fatura Tutarı',t.invoice,'blue','file','Faturaların net toplamı'],['Toplam Ödenen',t.payment,'green','wallet','Kayıtlı ödeme toplamı'],['Kalan Borç',t.debt,'red','arrow','Ödenmeyi bekleyen tutar'],['Toplam Tevkifat',t.withheld,'purple','percent','KDV üzerinden hesaplanan'],['Portföydeki Çek / Senet',sum(c.filter(x=>x.status==='Portföyde'),x=>x.amount),'orange','bank',c.length+' çek / senet kaydı'],['Net Cari Bakiye',t.debt,'cyan','transfer','Borç bakiyesi']].map(([l,v,color,ico,sub])=>`<div class="stat ${color} rounded-xl border"><div class="stathead flex items-center justify-between"><span>${l}</span><span class="iconbox">${icon(ico,19)}</span></div><strong class="tabular-nums">${money(v)}</strong><div class="statbottom"><span class="microdot"></span>${sub}</div></div>`).join('')}</div>`}
function chart(){const invoices=bills(),payments=pays(),months=['Haz','Tem','Ağu','Eyl','Eki','Kas'],t=totals(),max=Math.max(2000000,...[6,7,8,9,10,11].map(m=>sum(invoices.filter(i=>i.date.startsWith('2026-'+String(m).padStart(2,'0'))),net)));let method=['Havale / EFT','Çek','Nakit','Kredi Kartı','Senet'].map(m=>({name:m,amount:sum(payments.filter(p=>p.method===m),p=>p.amount)})).filter(x=>x.amount>0);const colors=['#314029','#62766d','#1b3c48','#96a889','#b8c6b2'];let accum=0,gradient=method.map((m,j)=>{const start=accum;accum+=t.payment?m.amount/t.payment*100:0;return `${colors[j]} ${start}% ${accum}%`}).join(',')||'#e2e7e0 0 100%';return `<div class="charts grid gap-5"><section class="card rounded-xl border">${cardHead('Finansal akış','Aylık fatura ve ödeme dağılımı','<span class="chartkey"><i></i>Fatura <i class="teal"></i>Ödeme</span>')}<div class="chart"><div class="ylabels">${[1,.75,.5,.25,0].map(n=>`<span>${(max*n/1000000).toLocaleString('tr-TR',{maximumFractionDigits:2})} mn ₺</span>`).join('')}</div><div class="plot">${months.map((m,j)=>{let prefix='2026-'+String(j+6).padStart(2,'0'),f=sum(invoices.filter(i=>i.date.startsWith(prefix)),net),p=sum(payments.filter(p=>p.date.startsWith(prefix)),p=>p.amount);return `<div class="barcolumn ${j===5?'current':''}"><div class="bars"><div tabindex="0" title="${m} fatura: ${money(f)}" style="height:${Math.max(2,f/max*180)}px"></div><div tabindex="0" title="${m} ödeme: ${money(p)}" style="height:${Math.max(2,p/max*180)}px"></div></div><span>${m}</span></div>`}).join('')}</div></div><div class="chartfooter">${icon('chart',16)}<b>${money(t.payment)}</b><span>toplam ödeme gerçekleştirildi</span><span class="lightbadge">2026</span></div></section><section class="card rounded-xl border">${cardHead('Ödeme yöntemleri','Ödemelerinizin dağılımı',icon('more'))}<div class="donut" style="background:conic-gradient(${gradient})"><div><small>Toplam ödeme</small><strong>${(t.payment/1000000).toLocaleString('tr-TR',{minimumFractionDigits:2,maximumFractionDigits:2})} mn ₺</strong><span>${payments.length} işlem</span></div></div><div class="legend">${method.map((m,j)=>`<div><i style="background:${colors[j]}"></i><span>${m.name}</span><b>${Math.round(m.amount/t.payment*100)}%</b><small>${money(m.amount)}</small></div>`).join('')||'<div class="smallnote">Henüz ödeme kaydedilmedi.</div>'}</div></section></div>`}
function overview(){let c=cheques().filter(c=>c.status==='Portföyde').sort((a,b)=>a.due.localeCompare(b.due));return metrics()+chart()+`<div class="lowergrid grid gap-5"><section class="card">${cardHead('Yaklaşan ve geçmiş vadeler <span class="count">'+c.length+'</span>','Planlı ödemelerinizi zamanında takip edin','<a class="textbutton" href="cek-senet.html">Tümünü gör '+icon('arrow',14)+'</a>')}${c.slice(0,3).map(x=>`<div class="dueitem"><div class="datebox ${x.due<today()?'red':'orange'}"><strong>${Number(x.due.slice(-2))}</strong><small>${new Date(x.due+'T12:00:00').toLocaleDateString('tr-TR',{month:'short'}).toLocaleUpperCase('tr')}</small></div><div><b>${esc(party(x.party))}</b><small>${esc(x.id)} · ${esc(x.bank)}</small></div><div class="dueright"><b>${money(x.amount)}</b><small class="${x.due<today()?'redtext':'orangetext'}">${x.due<today()?'Vadesi geçti':fmtDate(x.due)+' vadeli'}</small></div></div>`).join('')||'<div class="empty">Yaklaşan vade bulunmuyor.</div>'}</section><section class="card">${cardHead('Son işlemler','Projenizdeki son finansal hareketler','<a class="textbutton" href="odemeler.html">Tümü '+icon('arrow',14)+'</a>')}${pays().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,3).map(p=>`<div class="activity"><span class="iconbox green">${icon('wallet',19)}</span><div><b>Ödeme kaydedildi</b><small>${esc(p.invoice)} · ${esc(p.method)}</small></div><div class="dueright"><b class="greentext">${money(p.amount)}</b><small>${fmtDate(p.date)}</small></div></div>`).join('')||'<div class="empty">Henüz ödeme yok.</div>'}</section></div><section class="card invoicecard">${cardHead('Son faturalar','Faturalarınız ve güncel ödeme durumları','<a class="textbutton" href="faturalar.html">Tüm faturalar '+icon('arrow',15)+'</a>')}${invoiceTable(bills().slice().sort((a,b)=>b.date.localeCompare(a.date)).slice(0,4))}</section>`+(state.project==='all'?`<section class="card">${cardHead('İnşaat karşılaştırması')}<div class="tablewrap"><table><thead><tr><th>İnşaat</th><th class="num">Fatura toplamı</th><th class="num">Ödenen</th><th class="num">Kalan borç</th></tr></thead><tbody>${db.projects.map((p,j)=>{const a=bills().filter(i=>i.project===j);return `<tr><td>${esc(p)}</td><td class="num">${money(sum(a,net))}</td><td class="num">${money(sum(a,paid))}</td><td class="num">${money(sum(a,remain))}</td></tr>`}).join('')}</tbody></table></div></section>`:'')}
function columnMenu(){return `<div id="columns" class="columns-menu hidden">${[['id','Fatura'],['party','Cari'],['date','Tarih'],['net','Net tutar'],['paid','Ödenen'],['remaining','Kalan'],['status','Durum']].map(([v,l])=>`<label class="checkboxline"><input type="checkbox" data-column="${v}" ${state.hidden.includes(v)?'':'checked'}>${l}</label>`).join('')}</div>`}
function invoicesPage(){return `<section class="card"><div class="toolbar"><div class="searchfield">${icon('search',17)}<input aria-label="Fatura ara" id="bill-search" placeholder="Fatura no, cari veya açıklama ara" value="${esc(state.search)}"></div><select aria-label="Ödeme durumu" id="status-filter">${options(['Tümü','Ödendi','Kısmi ödendi','Ödenmedi'],state.status)}</select>${button('Sütunlar','columns','settings')}${button('Excel (CSV)','export','download')}</div>${columnMenu()}<div id="invoice-table">${invoiceTable(filteredBills())}</div></section>`}
function paymentsPage(){const rows=pays().filter(p=>(p.id+' '+p.invoice+' '+p.method+' '+party(db.invoices.find(i=>i.id===p.invoice)?.party)).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr')));return `<section class="card">${cardHead('Ödeme hareketleri','Bağlı fatura ve ödeme yöntemleri',`<b>${money(sum(rows,p=>p.amount))}</b>`)}<div class="tablewrap"><table><thead><tr><th>İşlem no</th><th>Bağlı fatura</th><th>Cari hesap</th><th>Tarih</th><th>Yöntem</th><th class="num">Tutar</th><th></th></tr></thead><tbody>${rows.map(p=>`<tr><td>${esc(p.id)}</td><td><button class="textbutton" data-detail="${esc(p.invoice)}">${esc(p.invoice)}</button></td><td>${esc(party(db.invoices.find(i=>i.id===p.invoice)?.party))}</td><td>${fmtDate(p.date)}</td><td>${badge(p.method)}</td><td class="num greentext">${money(p.amount)}</td><td><button class="table-action" aria-label="Ödemeyi sil" data-action="delete-payment" data-id="${esc(p.id)}">${icon('trash',15)}</button></td></tr>`).join('')}</tbody><tfoot><tr><td colspan="5">Toplam · ${rows.length} ödeme</td><td class="num">${money(sum(rows,p=>p.amount))}</td><td></td></tr></tfoot></table></div></section>`}
function withholdingPage(){const rows=bills().filter(i=>i.rate>0);return `<div class="summarythree grid grid-cols-1 md:grid-cols-3 gap-4">${[.2,.5,.7].map(r=>`<div class="card metric">${badge(r*10+'/10 Tevkifat','purple')}<strong>${money(sum(rows.filter(i=>i.rate===r),i=>i.base*i.vat/100*i.rate))}</strong><small>KDV-2 kapsamında takip edilen tutar</small></div>`).join('')}</div><section class="card">${cardHead('Tevkifat ve KDV-2 takibi','Fatura üzerinden hesaplanan dönem özeti',button('Excel (CSV)','export','download'))}<div class="tablewrap"><table><thead><tr><th>Fatura</th><th>Cari hesap</th><th class="num">Matrah</th><th class="num">KDV</th><th>Oran</th><th class="num">Tevkifat</th></tr></thead><tbody>${rows.map(i=>`<tr data-detail="${esc(i.id)}"><td>${esc(i.id)}</td><td>${esc(party(i.party))}</td><td class="num">${money(i.base)}</td><td class="num">${money(i.base*i.vat/100)}</td><td>${badge(i.rate*10+'/10','purple')}</td><td class="num"><b class="purpletext">${money(i.base*i.vat/100*i.rate)}</b></td></tr>`).join('')}</tbody></table></div><div class="totalbar">Toplam tevkifat <strong>${money(sum(rows,i=>i.base*i.vat/100*i.rate))}</strong></div></section>`}
function checksPage(){const c=cheques(),rows=c.filter(x=>(state.tab==='Tümü'||x.type===state.tab)&&(x.id+' '+party(x.party)).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr')));return `<div class="summarythree">${['Portföyde','Tahsil edildi','Vadesi geçmiş'].map(s=>`<div class="card metric"><small>${s}</small><strong class="${s==='Vadesi geçmiş'?'redtext':''}">${money(sum(c.filter(x=>s==='Vadesi geçmiş'?x.due<today()&&x.status==='Portföyde':x.status===s),x=>x.amount))}</strong></div>`).join('')}</div><div class="warning">${icon('clock')}Vadesi geçen kayıtları kontrol ederek tahsilat ve ödeme durumlarını güncelleyiniz.</div><section class="card"><div class="toolbar">${['Tümü','Çek','Senet'].map(s=>`<button class="${state.tab===s?'primary':''}" data-action="check-tab" data-tab="${s}">${s}</button>`).join('')}</div><div class="tablewrap"><table><thead><tr><th>Belge no</th><th>Cari hesap</th><th>Banka / Tür</th><th>Vade</th><th>Kalan gün</th><th class="num">Tutar</th><th>Durum</th></tr></thead><tbody>${rows.map(c=>{const days=Math.ceil((Date.parse(c.due)-Date.parse(today()))/86400000);return `<tr class="${days<0&&c.status==='Portföyde'?'late':''}"><td><b>${esc(c.id)}</b></td><td>${esc(party(c.party))}</td><td>${esc(c.bank)}<small>${esc(c.type)}</small></td><td>${fmtDate(c.due)}</td><td>${badge(days<0?Math.abs(days)+' gün gecikti':days+' gün kaldı',days<0?'red':days<=(db.warning||7)?'orange':'blue')}</td><td class="num">${money(c.amount)}</td><td><select aria-label="Çek durumu" data-check-status="${esc(c.id)}">${options(['Portföyde','Tahsil edildi','Ödendi','Ciro edildi','İade edildi','Karşılıksız'],c.status)}</select></td></tr>`}).join('')}</tbody></table></div></section>`}
function partyBalance(p){const r=bills().filter(i=>i.party===p.id);return {invoice:sum(r,net),payment:sum(r,paid),balance:sum(r,remain)}}
function partiesPage(){const rows=db.parties.filter(p=>(!['120 Alıcılar','320 Satıcılar'].includes(state.page)||p.type===state.page)&&(p.name+' '+p.code).toLocaleLowerCase('tr').includes(state.search.toLocaleLowerCase('tr')));return `<section class="card">${cardHead('Cari hesap listesi','120 Alıcılar · 320 Satıcılar',button('Excel (CSV)','export','download'))}<div class="tablewrap"><table><thead><tr><th>Cari kodu</th><th>Ünvan</th><th>Hesap türü</th><th class="num">Fatura toplamı</th><th class="num">Net bakiye</th><th></th></tr></thead><tbody>${rows.map(p=>{let t=partyBalance(p);return `<tr data-party="${esc(p.id)}"><td class="link">${esc(p.code)}</td><td><b>${esc(p.name)}</b></td><td>${esc(p.type)}</td><td class="num">${money(t.invoice)}</td><td class="num ${p.type==='120 Alıcılar'?'greentext':'redtext'}">${money(t.balance)} ${p.type==='120 Alıcılar'?'Alacak':'Borç'}</td><td>${icon('chevron',15)}</td></tr>`}).join('')}</tbody></table></div></section>`}
function ledgerRows(){let rows=[];for(const i of bills().filter(i=>(!state.cari||i.party===state.cari)&&(!state.start||i.date>=state.start)&&(!state.end||i.date<=state.end))){rows.push({date:i.date,id:i.id,name:party(i.party),desc:i.desc,debit:net(i),credit:0});}for(const p of db.payments){let i=db.invoices.find(i=>i.id===p.invoice);if(i&&scoped(i)&&(!state.cari||i.party===state.cari)&&(!state.start||p.date>=state.start)&&(!state.end||p.date<=state.end)&&(state.period==='all'||p.date.startsWith(state.period)))rows.push({date:p.date,id:p.id,name:party(i.party),desc:p.method+' · '+i.id,debit:0,credit:p.amount})}return rows.sort((a,b)=>a.date.localeCompare(b.date)||a.id.localeCompare(b.id))}
function ledgerTable(){let running=0;const rows=ledgerRows();return `<div class="tablewrap"><table class="document-table"><thead><tr><th>Tarih</th><th>Belge / Açıklama</th><th class="num">Borç</th><th class="num">Alacak</th><th class="num">Yürüyen bakiye</th></tr></thead><tbody>${rows.map(r=>{running+=r.debit-r.credit;return `<tr><td>${fmtDate(r.date)}</td><td><b>${esc(r.id)}</b><small>${esc(r.desc)}</small></td><td class="num">${money(r.debit)}</td><td class="num">${money(r.credit)}</td><td class="num"><b>${money(running)}</b></td></tr>`}).join('')}</tbody><tfoot><tr><td colspan="2">Dönem toplamı</td><td class="num">${money(sum(rows,r=>r.debit))}</td><td class="num">${money(sum(rows,r=>r.credit))}</td><td class="num">${money(running)}</td></tr></tfoot></table></div>`}
function statementPage(){return `<div class="statementlayout grid gap-5"><section class="card statementfilters"><h2>Ekstre filtreleri</h2>${selectField('Cari hesap','ledgerParty',[['','Tüm cari hesaplar'],...db.parties.map(p=>[p.id,p.name])],state.cari,'id="ledger-party"')}${field('Başlangıç','ledgerStart','date',state.start,'id="ledger-start"')}${field('Bitiş','ledgerEnd','date',state.end,'id="ledger-end"')}${button('Yazdır / PDF Kaydet','print','print')}${button('Excel (CSV)','export','download')}<p class="smallnote">PDF için yazdır penceresinde “PDF olarak kaydet” seçin. Ekstre, seçilen dönemin hareketlerini gösterir.</p></section><section class="card paper"><div class="paperhead">${db.logo?`<img class="logoimg" src="${esc(db.logo)}" alt="Firma logosu">`:icon('building',30)}<div><h2>${esc(db.company)}</h2><small>${esc(scopeName())}</small></div><b>HESAP EKSTRESİ</b></div><p>${state.cari?esc(party(state.cari)):'Tüm cari hesaplar'}<span class="floatright">${fmtDate(today())}</span></p><div class="daterange mb-4">${state.start?fmtDate(state.start):'Başlangıç'} – ${state.end?fmtDate(state.end):'Bugün'} · Tutarlar TRY / ₺</div>${ledgerTable()}</section></div>`}
const REPORTS=['Proje finansal özet raporu','Cari bakiye raporu','Fatura ve ödeme raporu','Tevkifat raporu'];
function reportBody(){if(state.report===0)return `<div class="tablewrap"><table><thead><tr><th>Proje</th><th class="num">Faturalar</th><th class="num">Ödemeler</th><th class="num">Kalan</th></tr></thead><tbody>${db.projects.map((name,j)=>{const r=bills().filter(i=>i.project===j);if(state.project!=='all'&&j!==Number(state.project))return '';return `<tr><td>${esc(name)}</td><td class="num">${money(sum(r,net))}</td><td class="num">${money(sum(r,paid))}</td><td class="num">${money(sum(r,remain))}</td></tr>`}).join('')}</tbody></table></div>`;if(state.report===1)return partiesPage();if(state.report===3)return withholdingPage();return invoiceTable(bills())}
function reportsPage(){return `<div class="reportgrid grid grid-cols-2 xl:grid-cols-4 gap-4">${REPORTS.map((r,j)=>`<button data-action="report" data-report="${j}" class="card reportbutton ${j===state.report?'chosen':''}"><span class="iconbox ${['blue','cyan','green','purple'][j]}">${icon('chart',23)}</span><b>${r}</b><small>Raporu görüntüle ${icon('arrow',14)}</small></button>`).join('')}</div><section class="card">${cardHead(REPORTS[state.report],'Seçili proje ve dönem kapsamında güncel kayıtlar',`<div class="actions">${button('PDF / Yazdır','print','print')}${button('Excel (CSV)','export','download')}</div>`)}${reportBody()}</section>`}
function settingsPage(){return `<div class="settingsgrid grid grid-cols-1 lg:grid-cols-2 gap-5"><section class="card settingscard"><h2>Firma bilgileri</h2><p>Belgelerinizde kullanılacak firma bilgileri</p><form id="company-form">${field('Firma ünvanı','company','text',db.company,'required')}${field('Vergi numarası','tax','text',db.tax||'')}${field('Firma adresi','address','text',db.address||'')}<label class="field"><span>Firma logosu (PNG/JPG, en fazla 500 KB)</span><input type="file" id="logo-file" accept="image/png,image/jpeg">${db.logo?`<img class="logoimg" src="${esc(db.logo)}" alt="Firma logosu">`:''}</label><button class="primary" type="submit">${icon('check',16)}Değişiklikleri kaydet</button></form></section><section class="card settingscard"><h2>İnşaat yönetimi</h2><p>Her proje bağımsız bir muhasebe dosyasıdır.</p>${db.projects.map((p,j)=>`<div class="projectline">${icon('building')}<b>${esc(p)}</b><button class="table-action" title="İnşaatı sil" data-action="delete-project" data-id="${j}">${icon('trash',15)}</button></div>`).join('')}${button('Yeni İnşaat Ekle','add-project','plus')}</section><section class="card settingscard"><h2>Tevkifat ve uyarılar</h2><p>Faturada seçilebilen oranlar: 0, 2/10, 5/10, 7/10, 9/10.</p><div class="warning">Mali müşavirinizle teyit ediniz.</div>${field('Vade uyarı süresi (gün)','warning','number',db.warning||7,'id="warning-days" min="1" max="90"')}<div class="readonly-note">Geliştiren / Author: Gündoğdu<br>Bu HTML sürümü ön yüz uygulamasıdır. Sunucu, kullanıcı yetkileri ve cihazlar arası senkronizasyon bağlı değildir.</div></section><section class="card settingscard"><h2>Veri yedekleme</h2><p>Veriler bu tarayıcıda saklanır. Düzenli olarak yedek indirin.</p>${button('Yedek indir','backup','download')}<label class="field mt-5"><span>Yedekten geri yükle (JSON)</span><input type="file" id="restore-file" accept=".json,application/json"></label><p class="smallnote">İçe aktarma mevcut tarayıcı kayıtlarını seçtiğiniz yedekle değiştirir.</p></section></div>`}
function content(){return state.page==='Genel Bakış'?overview():state.page==='Faturalar'?invoicesPage():state.page==='Ödemeler'?paymentsPage():state.page==='Tevkifat'?withholdingPage():state.page==='Çek / Senet'?checksPage():['Cari Hesaplar','120 Alıcılar','320 Satıcılar'].includes(state.page)?partiesPage():state.page==='Hesap Ekstresi'?statementPage():state.page==='Raporlar'?reportsPage():settingsPage()}
function primaryKind(){return state.page==='Ödemeler'?'payment':state.page==='Çek / Senet'?'check':['Cari Hesaplar','120 Alıcılar','320 Satıcılar'].includes(state.page)?'party':'invoice'}
function shell(){const kind=primaryKind(),label=state.page==='Genel Bakış'?'Yeni işlem':{payment:'Ödeme Ekle',check:'Çek / Senet Ekle',party:'Cari Ekle',invoice:'Fatura Ekle'}[kind];return `<div id="application" class="app"><aside id="sidebar"><div class="brand"><div class="brandmark">${icon('building',25)}</div><div class="brandtext">Gündoğdu İnşaat<small>MUHASEBE TAKİP PANELİ</small></div><button class="collapse" data-action="collapse" aria-label="Menüyü daralt">${icon('menu',16)}</button></div><div class="projectpick"><small>ÇALIŞMA ALANI</small>${icon('building',19)}<select aria-label="İnşaat seçimi" id="project-select">${options([['all','Tüm İnşaatlar'],...db.projects.map((p,j)=>[j,p]),['new','+ Yeni İnşaat Ekle']],state.project)}</select></div><div class="navlabel">ANA MENÜ</div><nav aria-label="Ana menü">${PAGES.map(([url,label,ico])=>`<a href="${url}" class="${state.page===label?'active ':''}${['120 Alıcılar','320 Satıcılar'].includes(label)?'sub':''}" title="${label}" ${state.page===label?'aria-current="page"':''}>${icon(ico,19)}<span>${label}</span>${label==='Faturalar'?`<em>${bills().length}</em>`:label==='Çek / Senet'?'<i class="dot"></i>':''}</a>`).join('')}</nav><div class="sidefoot"><div class="secure">${icon('check',16)}<span>Finansınız kontrol altında<small>Tarayıcıda otomatik kayıt</small></span></div><a href="ayarlar.html" class="user flex items-center gap-3"><span class="avatar">MY</span><span>Mehmet Yılmaz<small>Yönetici</small></span>${icon('more')}</a></div></aside><div class="main"><header><div class="breadcrumbs"><button class="mobiletoggle" data-action="mobile-menu" aria-label="Menüyü aç">${icon('menu')}</button><span>Çalışma alanı</span>${icon('chevron',14)}<b>${state.page}</b></div><div class="toptools"><form id="global-search-form" class="globalsearch">${icon('search',17)}<input id="global-search" name="q" aria-label="Genel arama" placeholder="Fatura, cari hesap ara..." value="${esc(state.search)}"><kbd>Ctrl K</kbd></form><button title="Temayı değiştir" aria-label="Temayı değiştir" data-action="theme">${icon('moon',19)}</button><a href="cek-senet.html" title="Vade bildirimleri" class="bell">${icon('bell',20)}<i></i></a><span class="avatar topavatar">MY</span></div></header><div class="context">${icon('building',17)}<b>${esc(scopeName())}</b><span class="contexttag">${state.project==='all'?'Toplu görünüm':'Aktif inşaat'}</span><span class="contextend"><span class="statusdot"></span> Veriler güncel <span>·</span> TRY / ₺</span></div><main><div class="pagetitle"><div><div class="eyebrow">PROJENİZİN FİNANSAL KONTROL MERKEZİ</div><h1>${state.page}</h1><p>${state.page==='Genel Bakış'?'Hoş geldiniz, Mehmet. Projenizin finansal durumuna birlikte göz atalım.':esc(scopeName())+' · Tüm finansal kayıtlarınız tek bir yerde.'}</p></div><div class="actions">${button('Dışa aktar','export','download')}${button(label,'add-'+kind,'plus',true)}</div></div><div class="periodrow"><div class="tabs"><button class="selected">${state.page==='Genel Bakış'?'Finansal özet':state.page}</button>${state.page==='Genel Bakış'?'<a class="flex items-center text-xs text-[#7a877f]" href="raporlar.html">Proje performansı</a>':''}</div><div class="datecontrol">${icon('calendar',15)}<select id="period-select" aria-label="Dönem seçimi">${options([['all','Tüm dönemler'],['2026-11','Kasım 2026'],['2026-10','Ekim 2026']],state.period)}</select></div></div><div id="page-content">${content()}</div><footer><span>İnşaat Muhasebe Takip Paneli <span class="footdot">·</span> Geliştiren: Gündoğdu</span><span><span class="statusdot"></span> Örnek veriler · Tarayıcıda otomatik kayıt</span></footer></main></div><dialog id="record-dialog" class="html-dialog" aria-label="Kayıt formu"></dialog><div id="toast" class="toast hidden" role="status"></div></div>`}
function saveDB(){try{localStorage.setItem('gundogdu-html-v1',JSON.stringify(db));return true}catch{storageOK=false;notice('Kayıt saklanamadı: tarayıcı depolama alanı dolu veya kapalı. Yedek indiriniz.');return false}}
function saveContext(){try{localStorage.setItem('gundogdu-context',JSON.stringify({project:state.project,period:state.period}));localStorage.setItem('gundogdu-columns',JSON.stringify(state.hidden))}catch{}}
function notice(text){const el=document.getElementById('toast');if(!el)return;el.textContent=text;el.classList.remove('hidden');clearTimeout(notice.timer);notice.timer=setTimeout(()=>el.classList.add('hidden'),4000)}
function renderAll(){const project=document.getElementById('project-select');if(project)project.innerHTML=options([['all','Tüm İnşaatlar'],...db.projects.map((p,j)=>[j,p]),['new','+ Yeni İnşaat Ekle']],state.project);const context=document.querySelector('.context>b');if(context)context.textContent=scopeName();const tag=document.querySelector('.contexttag');if(tag)tag.textContent=state.project==='all'?'Toplu görünüm':'Aktif inşaat';const count=document.querySelector('nav em');if(count)count.textContent=bills().length;const period=document.getElementById('period-select');if(period)period.value=state.period;const caption=document.querySelector('.pagetitle p');if(caption&&state.page!=='Genel Bakış')caption.textContent=scopeName()+' · Tüm finansal kayıtlarınız tek bir yerde.';renderContent();saveContext()}
function renderContent(){document.getElementById('page-content').innerHTML=content()}
function download(name,data,type='text/csv;charset=utf-8'){const b=new Blob([data],{type}),a=document.createElement('a');a.href=URL.createObjectURL(b);a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)}
function csvCell(x){let s=String(x??'');if(/^[=+@-]/.test(s))s="'"+s;return '"'+s.replace(/"/g,'""')+'"'}
function exportData(){let rows;if(state.page==='Hesap Ekstresi'){let running=0;rows=[['Tarih','Belge','Cari','Açıklama','Borç','Alacak','Yürüyen bakiye'],...ledgerRows().map(r=>{running+=r.debit-r.credit;return [r.date,r.id,r.name,r.desc,r.debit,r.credit,running]})]}else if(state.page==='Ödemeler'){rows=[['İşlem','Fatura','Tarih','Yöntem','Tutar'],...pays().map(p=>[p.id,p.invoice,p.date,p.method,p.amount])]}else if(state.page==='Çek / Senet'){rows=[['Belge','Tür','Cari','Banka','Vade','Tutar','Durum'],...cheques().filter(c=>state.tab==='Tümü'||c.type===state.tab).map(c=>[c.id,c.type,party(c.party),c.bank,c.due,c.amount,c.status])]}else if(['Cari Hesaplar','120 Alıcılar','320 Satıcılar'].includes(state.page)||state.page==='Raporlar'&&state.report===1){rows=[['Kod','Ünvan','Hesap','Fatura toplamı','Ödenen','Bakiye'],...db.parties.filter(p=>!['120 Alıcılar','320 Satıcılar'].includes(state.page)||p.type===state.page).map(p=>{let t=partyBalance(p);return [p.code,p.name,p.type,t.invoice,t.payment,t.balance]})]}else if(state.page==='Raporlar'&&state.report===0){rows=[['Proje','Fatura toplamı','Ödenen','Kalan'],...db.projects.map((p,j)=>{const r=bills().filter(i=>i.project===j);return [p,sum(r,net),sum(r,paid),sum(r,remain)]}).filter((r,j)=>state.project==='all'||j===Number(state.project))]}else{let data=state.page==='Tevkifat'||state.page==='Raporlar'&&state.report===3?bills().filter(i=>i.rate>0):filteredBills();rows=[['Fatura','İnşaat','Cari','Tarih','Matrah','KDV','Tevkifat','Net tutar','Ödenen','Kalan'],...data.map(i=>[i.id,db.projects[i.project],party(i.party),i.date,i.base,i.base*i.vat/100,i.base*i.vat/100*i.rate,net(i),paid(i),remain(i)])]}download('gundogdu-'+(PAGES.find(p=>p[1]===state.page)?.[0]||'rapor').replace('.html','')+'.csv','\uFEFF'+rows.map(r=>r.map(csvCell).join(';')).join('\r\n'));notice('Excel ile açılabilir CSV dosyası indirildi.')}
function backup(){download('gundogdu-muhasebe-yedek.json',JSON.stringify(db,null,2),'application/json');notice('Yedek indirildi.')}
function closeDialog(){const el=document.getElementById('record-dialog');el.close();el.innerHTML='';lastFocus?.focus?.()}
function showDialog(html){lastFocus=document.activeElement;const dialog=document.getElementById('record-dialog');if(dialog.open)dialog.close();dialog.innerHTML=html;dialog.showModal();const f=dialog.querySelector('input:not([type=hidden]),select,button');f?.focus()}
function dialogFrame(title,body,kind,footer=''){return `<form id="record-form" data-kind="${kind}"><div class="cardhead"><div><h2>${title}</h2><p>${esc(scopeName())} · Yeni kayıt</p></div><button type="button" data-action="close" aria-label="Kapat">${icon('close',21)}</button></div><div class="modalbody">${body}</div><div id="form-error" class="formerror" role="alert"></div><div class="modalfooter"><button type="button" data-action="close">Vazgeç</button>${footer||'<button type="submit" class="primary">'+icon('check',16)+'Kaydet</button>'}</div></form>`}
const partyOptions=()=>db.parties.map(p=>[p.id,p.name]);
function newRecord(kind,pre={}){const d=today(),project=state.project==='all'?0:Number(state.project);if(kind==='invoice'){showDialog(dialogFrame('Fatura Ekle',`<div class="stepper"><b id="step-one-label" class="current">1. Belge ve proje</b>${icon('chevron',16)}<b id="step-two-label">2. Fatura bilgileri</b></div><div id="invoice-step-one">${selectField('İnşaat','project',db.projects.map((p,j)=>[j,p]),project)}<div class="uploadarea">${icon('upload',28)}<b>Fatura belgesini yükleyin</b><p>PDF, JPG veya PNG · Bilgileri sonraki adımda girin.</p><input type="file" name="document" accept=".pdf,.jpg,.jpeg,.png"><small>Belge adı kayda eklenir. Otomatik okuma ve sunucuya dosya yükleme bağlı değildir.</small></div></div><div id="invoice-step-two" class="hidden">${field('Fatura numarası','id','text','FTR-'+Date.now())}${selectField('Cari hesap','party',partyOptions(),pre.party||db.parties[0]?.id)}<div class="formgrid">${field('Fatura tarihi','date','date',d)}${field('Vade tarihi','due','date',d)}${field('Matrah (₺)','base','number','','min="0.01" step="0.01" data-calc')}${selectField('KDV oranı','vat',[[0,'%0'],[1,'%1'],[10,'%10'],[20,'%20']],20,'data-calc')}</div>${selectField('Tevkifat oranı','rate',[[0,'Tevkifat yok'],[.2,'2/10'],[.5,'5/10'],[.7,'7/10'],[.9,'9/10']],0,'data-calc')}${field('Açıklama','desc')}<div id="invoice-calculation" class="calculations"></div></div>`,kind,`<button type="button" class="primary" id="invoice-next" data-action="invoice-next">Bilgileri gir ${icon('arrow',16)}</button><button type="submit" id="invoice-save" class="primary hidden">${icon('check',16)}Kaydet</button>`));calcInvoice();return}
if(kind==='payment'){showDialog(dialogFrame('Ödeme Ekle',`${selectField('Cari hesap','party',partyOptions(),pre.party||db.parties[0]?.id,'id="payment-party"')}<label class="field"><span>Ödeme yapılacak açık faturalar</span></label><div id="open-invoices" class="invoicechoices"></div><div class="formgrid">${field('Ödeme tutarı (₺)','amount','number',pre.amount||'','required min="0.01" step="0.01" id="payment-amount"')}${field('Ödeme tarihi','date','date',d,'required')}</div>${selectField('Ödeme yöntemi','method',['Havale / EFT','Nakit','Kredi Kartı','Çek','Senet'],'Havale / EFT','id="payment-method"')}<div id="payment-extra" class="hidden"><div class="formgrid">${field('Belge numarası','number')}${field('Vade tarihi','due','date',d)}${field('Banka','bank')}</div></div><p id="payment-warning" class="smallnote"></p>`,kind));renderOpenInvoices(pre.invoice);return}
if(kind==='party'){showDialog(dialogFrame('Cari Hesap Ekle',`${field('Ünvan','name','text','','required')}${selectField('Hesap türü','type',['320 Satıcılar','120 Alıcılar'],state.page==='120 Alıcılar'?'120 Alıcılar':'320 Satıcılar')}${field('Cari kodu','code','text','','required')}${field('Vergi numarası','tax')}`,kind));return}
if(kind==='project'){showDialog(dialogFrame('İnşaat Ekle',field('İnşaat adı','name','text','','required'),kind));return}
if(kind==='check'){showDialog(dialogFrame('Çek / Senet Ekle',`${selectField('İnşaat','project',db.projects.map((p,j)=>[j,p]),project)}${selectField('Cari hesap','party',partyOptions(),db.parties[0]?.id)}<div class="formgrid">${field('Belge numarası','id','text','','required')}${selectField('Tür','type',['Çek','Senet'],'Çek')}${field('Tutar (₺)','amount','number','','required min="0.01" step="0.01"')}${field('Vade tarihi','due','date',d,'required')}</div>${field('Banka','bank')}`,kind))}}
function calcInvoice(){const f=document.getElementById('record-form');if(!f)return;const data=new FormData(f),b=Number(data.get('base'))||0,v=Number(data.get('vat'))||0,r=Number(data.get('rate'))||0,vat=b*v/100,w=vat*r;document.getElementById('invoice-calculation').innerHTML=`<span>Matrah <b>${money(b)}</b></span><span>KDV <b>${money(vat)}</b></span><span>Tevkifat <b>${money(w)}</b></span><span>Tahsil edilecek KDV <b>${money(vat-w)}</b></span><strong>Ödenecek net <b>${money(b+vat-w)}</b></strong>`}
function renderOpenInvoices(selected=''){const form=document.getElementById('record-form'),id=form.elements.party.value,rows=bills().filter(i=>i.party===id&&remain(i)>0);document.getElementById('open-invoices').innerHTML=rows.map(i=>`<label><input type="checkbox" name="invoiceIds" value="${esc(i.id)}" ${i.id===selected?'checked':''}><span>${esc(i.id)}</span><b>${money(remain(i))}</b></label>`).join('')||'<p class="p-4 smallnote">Bu carinin seçili projede açık faturası bulunmuyor.</p>';paymentWarning()}
function paymentWarning(){const f=document.getElementById('record-form');if(!f)return;const data=new FormData(f),ids=data.getAll('invoiceIds'),limit=sum(bills().filter(i=>ids.includes(i.id)),remain),amount=Number(data.get('amount'));const el=document.getElementById('payment-warning');if(el){el.textContent=amount>limit?'Ödeme tutarı seçilen faturaların kalan tutarını aşamaz.':'Seçili faturaların kalan toplamı: '+money(limit);el.className=amount>limit?'redtext text-xs':'smallnote'}}
function formError(text){document.getElementById('form-error').textContent=text}
function rounded(n){return Math.round(n*100)/100}
function submitRecord(form){const data=new FormData(form),v=Object.fromEntries(data.entries()),kind=form.dataset.kind;formError('');if(kind==='invoice'){if(!v.id?.trim()||!v.date||!v.due||!v.party||!Number.isFinite(Number(v.base))||Number(v.base)<=0)return formError('Fatura numarası, tarih, cari ve pozitif matrah tutarı giriniz.');if(db.invoices.some(i=>i.id===v.id.trim()))return formError('Bu fatura numarası zaten kayıtlı.');db.invoices.push({id:v.id.trim(),project:Number(v.project),party:v.party,date:v.date,due:v.due,base:rounded(Number(v.base)),vat:Number(v.vat),rate:Number(v.rate),desc:v.desc||'',file:form.elements.document.files?.[0]?.name||''})}
if(kind==='payment'){const ids=data.getAll('invoiceIds'),rows=bills().filter(i=>ids.includes(i.id)&&i.party===v.party),amount=rounded(Number(v.amount)),limit=rounded(sum(rows,remain));if(!rows.length||!Number.isFinite(amount)||amount<=0)return formError('En az bir açık fatura seçip geçerli ödeme tutarı giriniz.');if(amount>limit)return formError('Fazla ödeme yapılamaz. En fazla '+money(limit)+' giriniz.');if(['Çek','Senet'].includes(v.method)){if(!v.number?.trim()||!v.due)return formError('Çek/senet için belge numarası ve vade zorunludur.');if(new Set(rows.map(i=>i.project)).size>1)return formError('Çek/senet için aynı inşaatın faturalarını seçiniz.');if(db.checks.some(c=>c.id===v.number.trim()))return formError('Bu çek/senet numarası zaten kayıtlı.')}let left=amount;const group=Date.now().toString(36);for(const i of rows){const n=Math.min(left,remain(i));if(n>0)db.payments.push({id:'ODM-'+group+'-'+i.id,invoice:i.id,amount:n,date:v.date,method:v.method,checkId:['Çek','Senet'].includes(v.method)?v.number.trim():null});left=rounded(left-n)}if(['Çek','Senet'].includes(v.method))db.checks.push({id:v.number.trim(),project:rows[0].project,party:v.party,amount,due:v.due,bank:v.bank||'—',status:'Portföyde',type:v.method})}
if(kind==='party'){if(!v.name?.trim()||!v.code?.trim())return formError('Ünvan ve cari kodu zorunludur.');if(db.parties.some(p=>p.code===v.code.trim()))return formError('Bu cari kodu zaten kayıtlı.');db.parties.push({id:Date.now().toString(),name:v.name.trim(),code:v.code.trim(),type:v.type,tax:v.tax||''})}
if(kind==='project'){if(!v.name?.trim())return formError('İnşaat adını giriniz.');if(db.projects.some(p=>p.toLocaleLowerCase('tr')===v.name.trim().toLocaleLowerCase('tr')))return formError('Bu inşaat zaten kayıtlı.');db.projects.push(v.name.trim())}
if(kind==='check'){if(!v.id?.trim()||!Number.isFinite(Number(v.amount))||Number(v.amount)<=0||!v.due)return formError('Belge numarası, pozitif tutar ve vade tarihi zorunludur.');if(db.checks.some(c=>c.id===v.id.trim()))return formError('Bu belge numarası zaten kayıtlı.');db.checks.push({...v,id:v.id.trim(),project:Number(v.project),amount:rounded(Number(v.amount)),status:'Portföyde',bank:v.bank||'—'})}
closeDialog();const saved=saveDB();renderAll();if(saved)notice('Kayıt başarıyla eklendi.')}
function detailInvoice(id){const i=db.invoices.find(i=>i.id===id);if(!i)return;showDialog(`<div class="cardhead"><h2>Fatura detayı</h2><button data-action="close" aria-label="Kapat">${icon('close',21)}</button></div><div class="detailheader">${badge(i.id)}<h2 class="mt-5 mb-2">${esc(party(i.party))}</h2><p>${esc(i.desc)}</p><p>${esc(db.projects[i.project])} · Vade: ${fmtDate(i.due)}</p>${i.file?'<p>Belge: '+esc(i.file)+' (dosya adı)</p>':''}</div><div class="detailrows">${[['Matrah',i.base],['KDV',i.base*i.vat/100],['Tevkifat',i.base*i.vat/100*i.rate],['Ödenecek net',net(i)],['Ödenen',paid(i)],['Kalan',remain(i)]].map(([l,n])=>`<div><span>${l}</span><b>${money(n)}</b></div>`).join('')}</div><div class="px-6 pb-5"><h3 class="mb-3">Ödemeler</h3>${db.payments.filter(p=>p.invoice===id).map(p=>`<div class="projectline">${fmtDate(p.date)} · ${esc(p.method)}<b>${money(p.amount)}</b></div>`).join('')||'<p>Henüz ödeme kaydedilmedi.</p>'}</div><div class="modalfooter">${button('Sil','delete-invoice','trash',false,`data-id="${esc(i.id)}"`)}${button('Ödeme Ekle','pay-invoice','wallet',true,`data-id="${esc(i.id)}"`)}</div>`)}
function detailParty(id,tab='Hareketler'){const p=db.parties.find(p=>p.id===id);if(!p)return;state.detailTab=tab;const t=partyBalance(p),rows=bills().filter(i=>i.party===id);let body='';if(tab==='Faturalar')body=invoiceTable(rows);else if(tab==='Ödemeler')body=`<div class="tablewrap"><table><thead><tr><th>İşlem</th><th>Tarih</th><th class="num">Tutar</th></tr></thead><tbody>${db.payments.filter(x=>rows.some(i=>i.id===x.invoice)).map(x=>`<tr><td>${esc(x.invoice)}</td><td>${fmtDate(x.date)}</td><td class="num">${money(x.amount)}</td></tr>`).join('')}</tbody></table></div>`;else if(tab==='Çek/Senet')body=`<div class="tablewrap"><table><thead><tr><th>Belge</th><th>Vade</th><th class="num">Tutar</th></tr></thead><tbody>${cheques().filter(c=>c.party===id).map(c=>`<tr><td>${esc(c.id)}</td><td>${fmtDate(c.due)}</td><td class="num">${money(c.amount)}</td></tr>`).join('')}</tbody></table></div>`;else{const prior=state.cari;state.cari=id;body=ledgerTable();state.cari=prior}showDialog(`<div class="cardhead"><div><h2>${esc(p.name)}</h2><p>${esc(p.code)} · ${esc(p.type)}</p></div><button data-action="close" aria-label="Kapat">${icon('close',21)}</button></div><div class="modalbody"><span class="badge ${p.type==='120 Alıcılar'?'green':'red'}">Net ${p.type==='120 Alıcılar'?'alacak':'borç'} bakiyesi</span><h1 class="my-4">${money(t.balance)}</h1><p>Fatura toplamı: ${money(t.invoice)} · Ödenen: ${money(t.payment)}</p><div class="tabs mt-5">${['Hareketler','Faturalar','Ödemeler','Çek/Senet'].map(s=>`<button class="${tab===s?'selected':''}" data-action="party-tab" data-id="${esc(id)}" data-tab="${s}">${s}</button>`).join('')}</div></div>${body}<div class="modalfooter">${button('Kapat','close','close')}<a class="btnlink" href="hesap-ekstresi.html?cari=${encodeURIComponent(id)}">Hesap ekstresine git ${icon('arrow',16)}</a></div>`)}
function validBackup(d){if(!d||typeof d!=='object'||!Array.isArray(d.projects)||!d.projects.length||!d.projects.every(p=>typeof p==='string')||!Array.isArray(d.parties)||!Array.isArray(d.invoices)||!Array.isArray(d.payments)||!Array.isArray(d.checks)||typeof d.company!=='string')return false;const partyIds=new Set(d.parties.map(p=>p.id));if(partyIds.size!==d.parties.length||!d.parties.every(p=>typeof p.id==='string'&&typeof p.name==='string'&&typeof p.code==='string'&&['120 Alıcılar','320 Satıcılar'].includes(p.type)))return false;const ids=new Set(d.invoices.map(i=>i.id)),number=n=>typeof n==='number'&&Number.isFinite(n)&&n>=0,date=s=>typeof s==='string'&&/^\d{4}-\d{2}-\d{2}$/.test(s),project=n=>Number.isInteger(n)&&n>=0&&n<d.projects.length;if(ids.size!==d.invoices.length||!d.invoices.every(i=>typeof i.id==='string'&&project(i.project)&&partyIds.has(i.party)&&number(i.base)&&number(i.vat)&&number(i.rate)&&i.rate<=1&&date(i.date)&&date(i.due)))return false;if(!d.payments.every(p=>ids.has(p.invoice)&&typeof p.id==='string'&&number(p.amount)&&date(p.date)&&typeof p.method==='string'))return false;if(d.invoices.some(i=>sum(d.payments.filter(p=>p.invoice===i.id),p=>p.amount)>net(i)+.01))return false;return d.checks.every(c=>typeof c.id==='string'&&project(c.project)&&partyIds.has(c.party)&&number(c.amount)&&date(c.due)&&typeof c.status==='string')}
function init(){state.page=document.body.dataset.page||'Genel Bakış';try{const raw=localStorage.getItem('gundogdu-html-v1');if(raw){const d=JSON.parse(raw);if(validBackup(d))db=d;else storageOK=false}const c=JSON.parse(localStorage.getItem('gundogdu-context')||'{}');state.project=c.project??'0';state.period=c.period??'all';const hidden=JSON.parse(localStorage.getItem('gundogdu-columns')||'[]');if(Array.isArray(hidden))state.hidden=hidden}catch{storageOK=false}if(state.project!=='all'&&!db.projects[Number(state.project)])state.project='all';const qs=new URLSearchParams(location.search);state.search=qs.get('q')||'';state.cari=qs.get('cari')||'';renderAll();try{document.getElementById('application').classList.toggle('dark',localStorage.getItem('gundogdu-theme')==='dark')}catch{}if(!storageOK)notice('Tarayıcı kaydı kullanılamadı veya yedek geçersiz. Örnek kayıtlar açıldı.');
document.addEventListener('click',e=>{const btn=e.target.closest('[data-action]');if(btn){const a=btn.dataset.action,id=btn.dataset.id;if(a==='close')return closeDialog();if(a==='theme'){const dark=document.getElementById('application').classList.toggle('dark');try{localStorage.setItem('gundogdu-theme',dark?'dark':'light')}catch{}return}if(a==='mobile-menu')return document.getElementById('sidebar').classList.toggle('mobileopen');if(a==='collapse')return document.getElementById('application').classList.toggle('collapsed');if(a==='columns')return document.getElementById('columns')?.classList.toggle('hidden');if(a==='export')return exportData();if(a==='backup')return backup();if(a==='print')return window.print();if(a.startsWith('add-'))return newRecord(a.slice(4));if(a==='invoice-next'){document.getElementById('invoice-step-one').classList.add('hidden');document.getElementById('invoice-step-two').classList.remove('hidden');document.getElementById('step-one-label').classList.remove('current');document.getElementById('step-two-label').classList.add('current');btn.classList.add('hidden');document.getElementById('invoice-save').classList.remove('hidden');document.querySelector('#record-form [name=id]').focus();return}if(a==='check-tab'){state.tab=btn.dataset.tab;renderContent();return}if(a==='report'){state.report=Number(btn.dataset.report);renderContent();return}if(a==='party-tab'){document.getElementById('record-dialog').close();detailParty(id,btn.dataset.tab);return}if(a==='pay-invoice'){const i=db.invoices.find(i=>i.id===id);closeDialog();newRecord('payment',{party:i.party,invoice:i.id,amount:remain(i)});return}if(a==='delete-invoice'){if(db.payments.some(p=>p.invoice===id))return notice('Bağlı ödeme bulunan fatura silinemez. Önce ilgili ödemeleri kaldırınız.');if(confirm(id+' faturası silinsin mi?')){db.invoices=db.invoices.filter(i=>i.id!==id);closeDialog();saveDB();renderAll();notice('Fatura silindi.')}return}if(a==='delete-payment'){const p=db.payments.find(p=>p.id===id);if(p?.checkId&&db.checks.some(c=>c.id===p.checkId))return notice('Ödeme bir çek/senede bağlıdır. Bu kayıt doğrudan silinemez.');if(confirm('Ödeme silinecek ve fatura kalanı yeniden hesaplanacak. Devam edilsin mi?')){db.payments=db.payments.filter(p=>p.id!==id);saveDB();renderAll();notice('Ödeme kaldırıldı.')}return}if(a==='delete-project'){const n=Number(id);if(db.invoices.some(i=>i.project===n)||db.checks.some(c=>c.project===n))return notice('Bağlı kayıtları olan inşaat silinemez.');if(db.projects.length===1)return notice('En az bir inşaat bulunmalıdır.');if(confirm('İnşaat silinsin mi?')){db.projects.splice(n,1);db.invoices.forEach(i=>{if(i.project>n)i.project--});db.checks.forEach(c=>{if(c.project>n)c.project--});state.project='all';saveDB();renderAll();notice('İnşaat kaldırıldı.')}return}}const detail=e.target.closest('[data-detail]');if(detail){detailInvoice(detail.dataset.detail);return}const p=e.target.closest('[data-party]');if(p)detailParty(p.dataset.party)});
document.addEventListener('submit',e=>{if(e.target.getAttribute('id')==='record-form'){e.preventDefault();submitRecord(e.target)}if(e.target.id==='company-form'){e.preventDefault();const d=new FormData(e.target);db.company=d.get('company').trim();db.tax=d.get('tax');db.address=d.get('address');if(saveDB())notice('Firma bilgileri kaydedildi.')}if(e.target.id==='global-search-form'){e.preventDefault();location.href='faturalar.html?q='+encodeURIComponent(new FormData(e.target).get('q')||'')}});
document.addEventListener('input',e=>{const el=e.target;if(el.matches('[data-calc]'))calcInvoice();if(el.id==='payment-amount')paymentWarning();if(el.id==='bill-search'){state.search=el.value;document.getElementById('invoice-table').innerHTML=invoiceTable(filteredBills())}});
document.addEventListener('change',async e=>{const el=e.target;if(el.id==='project-select'){if(el.value==='new'){el.value=state.project;return newRecord('project')}state.project=el.value;saveContext();renderAll()}if(el.id==='period-select'){state.period=el.value;saveContext();renderAll()}if(el.id==='status-filter'){state.status=el.value;renderContent()}if(el.dataset.column){state.hidden=el.checked?state.hidden.filter(c=>c!==el.dataset.column):[...state.hidden,el.dataset.column];saveContext();document.getElementById('invoice-table').innerHTML=invoiceTable(filteredBills())}if(el.matches('[data-calc]'))calcInvoice();if(el.id==='payment-party')renderOpenInvoices();if(el.name==='invoiceIds')paymentWarning();if(el.id==='payment-method'){document.getElementById('payment-extra').classList.toggle('hidden',!['Çek','Senet'].includes(el.value))}if(el.dataset.checkStatus){const c=db.checks.find(c=>c.id===el.dataset.checkStatus);if(c)c.status=el.value;saveDB();renderContent();notice('Durum güncellendi.')}if(['ledger-party','ledger-start','ledger-end'].includes(el.id)){const key={'ledger-party':'cari','ledger-start':'start','ledger-end':'end'}[el.id];state[key]=el.value;renderContent()}if(el.id==='warning-days'){const n=Number(el.value);if(n<1||n>90){notice('1–90 arasında gün giriniz.');return}db.warning=n;saveDB()}if(el.id==='logo-file'){const f=el.files?.[0];if(!f)return;if(!['image/png','image/jpeg'].includes(f.type)||f.size>500000)return notice('500 KB altında PNG veya JPG seçiniz.');const reader=new FileReader();reader.onload=()=>{db.logo=String(reader.result);saveDB();renderContent();notice('Logo kaydedildi.')};reader.readAsDataURL(f)}if(el.id==='restore-file'){try{const f=el.files?.[0];if(!f)return;const d=JSON.parse(await f.text());if(!validBackup(d))throw Error();if(confirm('Mevcut kayıtlar bu yedek ile değiştirilsin mi?')){db=d;state.project='all';saveDB();renderAll();notice('Yedek başarıyla yüklendi.')}}catch{notice('Yedek dosyası veya veri ilişkileri geçersiz. Kayıtlar değiştirilmedi.')}}});
document.addEventListener('keydown',e=>{if((e.ctrlKey||e.metaKey)&&e.key==='k'){e.preventDefault();document.getElementById('global-search')?.focus()}});document.addEventListener('cancel',e=>{if(e.target.id==='record-dialog'){e.preventDefault();closeDialog()}},true);document.addEventListener('click',e=>{if(e.target.id==='record-dialog'){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeDialog()}});}
if(typeof document!=='undefined')document.addEventListener('DOMContentLoaded',init);
